# -*- coding: utf-8 -*-
"""
HOÀN THIỆN SÁP NHẬP TOÀN TỈNH - BƯỚC 1

Mục tiêu:
- Chuẩn hóa nốt giao diện sáp nhập phát sinh, không lộ thuật ngữ kỹ thuật không cần thiết.
- Chuẩn hóa Bảng điều khiển toàn tỉnh sang trạng thái tiếng Việt.
- Thêm Xuất Excel tổng hợp toàn bộ phương án và Xuất Excel cần xử lý.
- Làm sạch danh sách sáp nhập phát sinh đã thực hiện gần đây.
- Không thực hiện sáp nhập, không chủ động ghi phocap.db.
"""
from __future__ import annotations
import base64, datetime as dt, hashlib, json, os, py_compile, shutil, traceback
from pathlib import Path

TITLE = "HOÀN THIỆN SÁP NHẬP TOÀN TỈNH - BƯỚC 1"
EMBEDDED_FILES = {'app/templates/data_tools/school_merger_dashboard_v45.html': '', 'app/templates/data_tools/school_merger_future_preview_v45.html': '', 'app/templates/data_tools/school_merger_future_result_v45.html': '', 'app/services/school_merger_future_service.py': '', 'app/routers/school_merger_future.py': ''}
EXPECTED_BASE_HASHES = {'app/templates/data_tools/school_merger_dashboard_v45.html': '327a8326ac11fe24740faabf0be0f02698ca48735d3df695fc54f3d60f30927e', 'app/templates/data_tools/school_merger_future_preview_v45.html': '3699b543baa1081560af0d8eb9ced69fc7df06227c560c4f82f8e33520ed0af5', 'app/templates/data_tools/school_merger_future_result_v45.html': '839f86fa1459ebc847975e285ae75ca4d6462b4250879e9e5ec5031196ba6e06', 'app/services/school_merger_future_service.py': '83460db158345a3cb8ad2354c0ee52302f497e253a3e24a70b79007a934a9881', 'app/routers/school_merger_future.py': 'e7ddc112a0198c61b58610a58b2d4b75243111e91a626f3ad52bb94bdea61d91'}
FINAL_HASHES = {'app/templates/data_tools/school_merger_dashboard_v45.html': '2646aba7b95c2a820773164805a516524a49df5a2652d2b337cec2362a5e2307', 'app/templates/data_tools/school_merger_future_preview_v45.html': '3e9e47253f54e841ee1c827264cfe58ae8b1cc7834dea643439e791cb2cb1f20', 'app/templates/data_tools/school_merger_future_result_v45.html': '9bef51360838ba8b9e4347e258c4a47864bcdf19ba0571206f225f8359ad1c7a', 'app/services/school_merger_future_service.py': 'db276a9c8ad81a4b8dc53f368de1dd7876300c096da5f66179719810304a085a', 'app/routers/school_merger_future.py': '5c7a5d4a954e0d8f1735cbd1d790d49cfe8656bb14bff18e163657b9baff6187'}


def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

def db_fingerprint(db: Path) -> str:
    h = hashlib.sha256()
    for p in [db, Path(str(db)+"-wal"), Path(str(db)+"-shm")]:
        h.update(p.name.encode("utf-8"))
        if p.exists():
            h.update(str(p.stat().st_size).encode("ascii"))
            h.update(sha256_file(p).encode("ascii"))
        else:
            h.update(b"MISSING")
    return h.hexdigest()

def fail(msg: str):
    raise RuntimeError(msg)

def main():
    cwd = Path.cwd().resolve()
    script_dir = Path(__file__).resolve().parent
    root = cwd if (cwd / "app").exists() else script_dir
    if not (root / "app").exists():
        fail(r"Không tìm thấy thư mục app. Hãy chép bộ cài vào C:\PhoCap và chạy tại C:\PhoCap.")
    db = root / "data" / "phocap.db"
    if not db.exists():
        fail(f"Không tìm thấy database: {db}")

    ts = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_hoan_thien_sap_nhap_toan_tinh_buoc_1_{ts}"
    export_dir = root / "exports" / "Hoan_Thien_Sap_Nhap_Toan_Tinh_Buoc_1"
    report_path = export_dir / f"bao_cao_{ts}.json"
    db_before = db_fingerprint(db)
    touched = []

    try:
        for rel in EMBEDDED_FILES:
            p = root / rel
            if not p.exists():
                fail(f"Thiếu tệp nền: {rel}")
            cur = sha256_file(p)
            if cur not in {EXPECTED_BASE_HASHES[rel], FINAL_HASHES[rel]}:
                fail(f"Tệp {rel} không đúng nền đã khóa. SHA hiện tại={cur}")

        backup_dir.mkdir(parents=True, exist_ok=True)
        for rel in EMBEDDED_FILES:
            src = root / rel
            dst = backup_dir / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

        for rel, b64 in EMBEDDED_FILES.items():
            p = root / rel
            p.write_bytes(base64.b64decode(b64))
            touched.append(rel)

        for rel, expected_hash in FINAL_HASHES.items():
            got = sha256_file(root / rel)
            if got != expected_hash:
                fail(f"SHA sau cài không đúng: {rel}")

        py_compile.compile(str(root / "app/routers/school_merger_future.py"), doraise=True)
        py_compile.compile(str(root / "app/services/school_merger_future_service.py"), doraise=True)

        dash = (root / "app/templates/data_tools/school_merger_dashboard_v45.html").read_text(encoding="utf-8")
        preview = (root / "app/templates/data_tools/school_merger_future_preview_v45.html").read_text(encoding="utf-8")
        result = (root / "app/templates/data_tools/school_merger_future_result_v45.html").read_text(encoding="utf-8")
        router = (root / "app/routers/school_merger_future.py").read_text(encoding="utf-8")
        service = (root / "app/services/school_merger_future_service.py").read_text(encoding="utf-8")
        combined = "\n".join([dash, preview, result, router, service])

        required = [
            "ĐẠT – CÓ THỂ XEM TRƯỚC",
            "CHẶN – CẦN XỬ LÝ",
            "Xuất Excel cần xử lý",
            "Xuất Excel tổng hợp",
            "Dữ liệu hệ thống đủ điều kiện kế thừa",
            "Mã trường:",
            "Hồ sơ đội ngũ kế thừa",
            "/bang-dieu-khien/xuat-tong-hop",
            "CAN_XU_LY",
            "target_school_name",
        ]
        for needle in required:
            if needle not in combined:
                fail(f"Thiếu nội dung hoàn thiện: {needle}")

        forbidden_visible = [
            "PASS – CÓ THỂ XEM TRƯỚC",
            "BLOCK – CẦN XỬ LÝ",
            "Xuất Excel BLOCK",
            "Chữ ký:</strong>",
            "school_id={{",
            "NGUỒN – ĐÃ INACTIVE",
            "Rollover đội ngũ",
            "Mã operation",
        ]
        visible_templates = "\n".join([dash, preview, result])
        for needle in forbidden_visible:
            if needle in visible_templates:
                fail(f"Giao diện vẫn còn thuật ngữ kỹ thuật: {needle}")

        db_after = db_fingerprint(db)
        if db_after != db_before:
            fail("Database/WAL đã thay đổi trong bộ cài. Đã dừng an toàn.")

        export_dir.mkdir(parents=True, exist_ok=True)
        report = {
            "installed_at": dt.datetime.now().isoformat(timespec="seconds"),
            "title_internal": TITLE,
            "database_unchanged": True,
            "backup_dir": str(backup_dir),
            "changes": [
                "Chuẩn hóa trạng thái bảng điều khiển sang ĐẠT/CHẶN.",
                "Thêm Xuất Excel tổng hợp toàn bộ phương án.",
                "Đổi Xuất Excel BLOCK thành Xuất Excel cần xử lý.",
                "Ẩn school_id/chữ ký/dấu vân tay khỏi giao diện sáp nhập phát sinh.",
                "Làm sạch màn hình kết quả sáp nhập phát sinh.",
                "Không thay đổi logic sáp nhập và không chạm chức năng Đổi tên trường.",
            ],
            "files": {rel: {"sha256": FINAL_HASHES[rel]} for rel in EMBEDDED_FILES},
        }
        report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")

        print()
        print("=" * 112)
        print("HOÀN THIỆN SÁP NHẬP TOÀN TỈNH - BƯỚC 1: CÀI ĐẶT THÀNH CÔNG")
        print("Database: KHÔNG THAY ĐỔI")
        print("Bảng điều khiển: ĐÃ CHUẨN HÓA ĐẠT/CHẶN")
        print("Xuất Excel cần xử lý: CÓ")
        print("Xuất Excel tổng hợp: CÓ")
        print("Sáp nhập phát sinh: GIỮ NGUYÊN CƠ CHẾ AN TOÀN")
        print("Đổi tên trường: GIỮ NGUYÊN")
        print(f"Backup mã nguồn: {backup_dir}")
        print(f"Báo cáo: {report_path}")
        print("=" * 112)

    except Exception as e:
        try:
            for rel in touched:
                bp = backup_dir / rel
                if bp.exists():
                    p = root / rel
                    p.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(bp, p)
        except Exception:
            pass
        print()
        print("=" * 112)
        print("DỪNG AN TOÀN - HOÀN THIỆN SÁP NHẬP TOÀN TỈNH - BƯỚC 1")
        print("Mã nguồn đã được khôi phục nếu đã chạm file.")
        print(f"Lỗi: {e}")
        print("Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.")
        print("=" * 112)
        if os.environ.get("PHOCAP_INSTALLER_DEBUG") == "1":
            traceback.print_exc()
        raise SystemExit(1)

if __name__ == "__main__":
    main()
